head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name        : RoushanTalky - News Magazine (StartupTalky Style)
Designer    : Roushan Gupta
Author URL  : Blogger Theme for Roushan Gupta
Version     : 1.0.0
License     : Free to use - keep the footer credit
----------------------------------------------- */
/* Variable definitions

<Group description="Brand Colors">
<Variable name="keycolor" description="Primary Color (Red)" type="color" default="#e5094b" value="#e5094b"/>
<Variable name="accentcolor" description="Gradient Partner Color" type="color" default="#ff5f6d" value="#ff5f6d"/>
<Variable name="darkcolor" description="Dark Color (Header/Footer)" type="color" default="#0e1424" value="#0e1424"/>
<Variable name="body.background" description="Page Background" type="color" default="#f4f6fa" value="#f4f6fa"/>
<Variable name="card.background" description="Card Background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="body.text.color" description="Body Text Color" type="color" default="#52606d" value="#52606d"/>
<Variable name="posts.title.color" description="Heading Color" type="color" default="#0e1424" value="#0e1424"/>
<Variable name="body.link.color" description="Link Color" type="color" default="$(keycolor)" value="#e5094b"/>
<Variable name="border.color" description="Border Color" type="color" default="#e6e9f0" value="#e6e9f0"/>
</Group>

<Group description="Typography">
<Variable name="bodyFontFamily" description="Body Font Family" type="string" default="Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif" value="Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif"/>
<Variable name="headingFontFamily" description="Heading Font Family" type="string" default="Sora, Inter, Segoe UI, Arial, sans-serif" value="Sora, Inter, Segoe UI, Arial, sans-serif"/>
<Variable name="bodyFontSize" description="Body Font Size" type="length" default="16px" min="13px" max="20px" value="16px"/>
</Group>

<Group description="Logo and Site">
<Variable name="logoUrl" description="Logo Image URL (leave empty for text logo)" type="string" default="" value=""/>
<Variable name="logoMark" description="Text Logo Short Name" type="string" default="RG" value="RG"/>
<Variable name="tagline" description="Homepage Tagline (after blog title)" type="string" default="Startup, Business, Technology and AI Stories" value="Startup, Business, Technology and AI Stories"/>
<Variable name="siteDescription" description="Default Meta Description" type="string" default="Roushan Gupta writes about startups, business, technology, AI tools and digital marketing. Read latest news, reviews, guides and success stories." value="Roushan Gupta writes about startups, business, technology, AI tools and digital marketing. Read latest news, reviews, guides and success stories."/>
<Variable name="siteCover" description="Default Share Image URL (1200x630)" type="string" default="" value=""/>
<Variable name="newsletterUrl" description="Newsletter Subscribe URL" type="string" default="" value=""/>
</Group>

<Group description="Personal Branding - Roushan Gupta">
<Variable name="authorName" description="Author Name" type="string" default="Roushan Gupta" value="Roushan Gupta"/>
<Variable name="authorRole" description="Author Role" type="string" default="Founder, Blogger and Startup Storyteller" value="Founder, Blogger and Startup Storyteller"/>
<Variable name="authorPhoto" description="Author Photo URL" type="string" default="https://ui-avatars.com/api/?name=Roushan+Gupta" value="https://ui-avatars.com/api/?name=Roushan+Gupta"/>
<Variable name="authorBio" description="Author Short Bio" type="string" default="I am Roushan Gupta. I research and write simple, practical stories about startups, business models, technology, AI tools and digital marketing so that founders and students can learn fast." value="I am Roushan Gupta. I research and write simple, practical stories about startups, business models, technology, AI tools and digital marketing so that founders and students can learn fast."/>
</Group>

<Group description="Social Links">
<Variable name="socialFacebook" description="Facebook URL" type="string" default="" value=""/>
<Variable name="socialX" description="X (Twitter) URL" type="string" default="" value=""/>
<Variable name="socialInstagram" description="Instagram URL" type="string" default="" value=""/>
<Variable name="socialLinkedin" description="LinkedIn URL" type="string" default="" value=""/>
<Variable name="socialYoutube" description="YouTube URL" type="string" default="" value=""/>
<Variable name="socialWhatsapp" description="WhatsApp Channel URL" type="string" default="" value=""/>
</Group>

*/

/* ==========================================================================
   1. RESET + BASE
   ========================================================================== */
:root{
  --rg-p:$(keycolor);
  --rg-p2:$(accentcolor);
  --rg-dark:$(darkcolor);
  --rg-bg:$(body.background);
  --rg-card:$(card.background);
  --rg-text:$(body.text.color);
  --rg-h:$(posts.title.color);
  --rg-link:$(body.link.color);
  --rg-bd:$(border.color);
  --rg-muted:#8b95a7;
  --rg-soft:#f7f8fb;
  --rg-grad:linear-gradient(120deg,$(keycolor) 0%,$(accentcolor) 100%);
  --rg-shadow:0 2px 10px rgba(14,20,36,.06);
  --rg-shadow-lg:0 18px 45px rgba(14,20,36,.14);
  --rg-r:14px;
  --rg-rs:10px;
  --rg-max:1240px;
  --rg-head-h:64px;
  --rg-ease:cubic-bezier(.22,.61,.36,1);
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{
  margin:0;padding:0;background:var(--rg-bg);color:var(--rg-text);
  font-family:$(bodyFontFamily);font-size:$(bodyFontSize);line-height:1.7;
  overflow-x:hidden;-webkit-font-smoothing:antialiased;
  transition:background .35s var(--rg-ease),color .35s var(--rg-ease);
}
img{max-width:100%;height:auto;border:0;display:block}
a{color:var(--rg-link);text-decoration:none;transition:color .25s var(--rg-ease)}
a:hover{color:var(--rg-p2)}
ul,ol{margin:0;padding:0;list-style:none}
h1,h2,h3,h4,h5,h6{font-family:$(headingFontFamily);color:var(--rg-h);margin:0 0 .5em;line-height:1.28;font-weight:800;letter-spacing:-.02em}
p{margin:0 0 1em}
button,input,select,textarea{font-family:inherit;font-size:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
:focus-visible{outline:2px solid var(--rg-p);outline-offset:2px}
.rg-h{font-family:$(headingFontFamily)}
.rg-container{width:100%;max-width:var(--rg-max);margin:0 auto;padding:0 18px}
.rg-sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.rg-icon{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:0 0 auto}
.rg-icon-fill{width:16px;height:16px;fill:currentColor;stroke:none}
::selection{background:var(--rg-p);color:#fff}
/* scrollbar */
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:var(--rg-soft)}
::-webkit-scrollbar-thumb{background:#c6cddb;border-radius:20px}
::-webkit-scrollbar-thumb:hover{background:var(--rg-p)}

/* ==========================================================================
   2. READING PROGRESS + BACK TO TOP
   ========================================================================== */
#rg-progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--rg-grad);z-index:9999;transition:width .12s linear}
#rg-top{position:fixed;right:20px;bottom:22px;width:46px;height:46px;border-radius:50%;background:var(--rg-grad);color:#fff;
  display:grid;place-items:center;z-index:900;opacity:0;visibility:hidden;transform:translateY(16px);
  transition:all .35s var(--rg-ease);box-shadow:0 8px 22px rgba(229,9,75,.35)}
#rg-top.show{opacity:1;visibility:visible;transform:translateY(0)}
#rg-top:hover{transform:translateY(-4px)}

/* ==========================================================================
   3. TOP BAR
   ========================================================================== */
.rg-topbar{background:var(--rg-dark);color:#c8d0e0;font-size:12.5px;position:relative;z-index:60}
.rg-topbar .rg-container{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:42px}
.rg-topbar-left{display:flex;align-items:center;gap:14px;min-width:0}
.rg-date{display:inline-flex;align-items:center;gap:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rg-live{display:inline-flex;align-items:center;gap:6px;color:#fff;font-weight:600}
.rg-live i{width:7px;height:7px;border-radius:50%;background:#25d366;box-shadow:0 0 0 0 rgba(37,211,102,.7);animation:rg-pulse 2s infinite}
@keyframes rg-pulse{0%{box-shadow:0 0 0 0 rgba(37,211,102,.6)}70%{box-shadow:0 0 0 8px rgba(37,211,102,0)}100%{box-shadow:0 0 0 0 rgba(37,211,102,0)}}
.rg-topbar-right{display:flex;align-items:center;gap:6px}
.rg-soc{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;color:#c8d0e0;background:rgba(255,255,255,.07);transition:all .3s var(--rg-ease)}
.rg-soc:hover{background:var(--rg-p);color:#fff;transform:translateY(-2px)}

/* ==========================================================================
   4. HEADER
   ========================================================================== */
.rg-header{background:var(--rg-card);border-bottom:1px solid var(--rg-bd);position:relative;z-index:55;transition:background .3s var(--rg-ease)}
.rg-header .rg-container{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:78px;padding-top:12px;padding-bottom:12px}
.rg-brand{display:flex;align-items:center;gap:11px;min-width:0}
.rg-logo{display:flex;align-items:center;gap:11px;color:var(--rg-h)}
.rg-logo:hover{color:var(--rg-h)}
.rg-logo img{max-height:52px;width:auto}
.rg-mark{width:44px;height:44px;border-radius:12px;background:var(--rg-grad);color:#fff;display:grid;place-items:center;
  font-family:$(headingFontFamily);font-weight:800;font-size:17px;letter-spacing:.5px;flex:0 0 auto;
  box-shadow:0 6px 16px rgba(229,9,75,.28);transition:transform .4s var(--rg-ease)}
.rg-logo:hover .rg-mark{transform:rotate(-8deg) scale(1.05)}
.rg-logo-text{display:flex;flex-direction:column;line-height:1.1;min-width:0}
.rg-logo-name{font-family:$(headingFontFamily);font-weight:800;font-size:25px;color:var(--rg-h);letter-spacing:-.6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rg-logo-name span{color:var(--rg-p)}
.rg-logo-tag{font-size:10.5px;letter-spacing:1.6px;text-transform:uppercase;color:var(--rg-muted);font-weight:600}
.rg-header-right{display:flex;align-items:center;gap:10px}
.rg-iconbtn{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;color:var(--rg-h);
  background:var(--rg-soft);border:1px solid var(--rg-bd);transition:all .3s var(--rg-ease)}
.rg-iconbtn:hover{background:var(--rg-p);border-color:var(--rg-p);color:#fff;transform:translateY(-2px)}
.rg-btn{display:inline-flex;align-items:center;gap:8px;padding:11px 22px;border-radius:50px;font-weight:700;font-size:14px;
  background:var(--rg-grad);color:#fff;box-shadow:0 8px 20px rgba(229,9,75,.25);transition:all .3s var(--rg-ease)}
.rg-btn:hover{color:#fff;transform:translateY(-2px);box-shadow:0 12px 26px rgba(229,9,75,.35)}
.rg-burger{display:none}

/* ==========================================================================
   5. STICKY NAV
   ========================================================================== */
.rg-nav{background:var(--rg-card);border-bottom:1px solid var(--rg-bd);position:sticky;top:0;z-index:80;
  transition:box-shadow .3s var(--rg-ease),background .3s var(--rg-ease)}
.rg-nav.stuck{box-shadow:0 8px 26px rgba(14,20,36,.1)}
.rg-nav .rg-container{display:flex;align-items:center;gap:16px;min-height:var(--rg-head-h)}
#rg-menu-list{display:flex;align-items:center;gap:2px;flex:1 1 auto;overflow-x:auto;scrollbar-width:none;-ms-overflow-style:none}
#rg-menu-list::-webkit-scrollbar{display:none}
#rg-menu-list li{position:relative;flex:0 0 auto}
#rg-menu-list a{display:inline-flex;align-items:center;gap:7px;padding:21px 14px;font-family:$(headingFontFamily);font-size:14.5px;
  font-weight:700;color:var(--rg-h);position:relative;white-space:nowrap;letter-spacing:-.2px}
#rg-menu-list a::after{content:"";position:absolute;left:14px;right:14px;bottom:14px;height:3px;border-radius:3px;
  background:var(--rg-grad);transform:scaleX(0);transform-origin:left;transition:transform .35s var(--rg-ease)}
#rg-menu-list a:hover,#rg-menu-list li.selected a{color:var(--rg-p)}
#rg-menu-list a:hover::after,#rg-menu-list li.selected a::after{transform:scaleX(1)}
.rg-nav-side{display:flex;align-items:center;gap:8px;flex:0 0 auto}
.rg-nav-label{font-size:11px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;color:var(--rg-p);
  padding:5px 12px;border-radius:50px;background:rgba(229,9,75,.08);white-space:nowrap}

/* mobile drawer */
#rg-drawer{position:fixed;inset:0 0 0 auto;width:min(84vw,340px);background:var(--rg-card);z-index:1000;
  transform:translateX(102%);transition:transform .42s var(--rg-ease);box-shadow:var(--rg-shadow-lg);overflow-y:auto;
  padding:20px;display:flex;flex-direction:column;gap:6px}
#rg-drawer.open{transform:translateX(0)}
#rg-drawer a{display:block;padding:13px 12px;border-bottom:1px solid var(--rg-bd);color:var(--rg-h);font-weight:700;font-family:$(headingFontFamily);font-size:15px}
#rg-drawer a:hover{color:var(--rg-p);padding-left:18px}
#rg-drawer .rg-drawer-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
#rg-overlay{position:fixed;inset:0;background:rgba(8,12,22,.55);z-index:999;opacity:0;visibility:hidden;transition:all .35s var(--rg-ease);backdrop-filter:blur(2px)}
#rg-overlay.show{opacity:1;visibility:visible}

/* ==========================================================================
   6. SEARCH OVERLAY
   ========================================================================== */
#rg-search{position:fixed;inset:0;z-index:1200;background:rgba(10,14,26,.93);display:grid;place-items:center;
  opacity:0;visibility:hidden;transition:all .35s var(--rg-ease);padding:20px}
#rg-search.open{opacity:1;visibility:visible}
#rg-search form{width:min(680px,100%);position:relative;transform:translateY(18px);transition:transform .45s var(--rg-ease)}
#rg-search.open form{transform:translateY(0)}
#rg-search input{width:100%;padding:22px 62px 22px 24px;border-radius:16px;border:2px solid rgba(255,255,255,.18);
  background:rgba(255,255,255,.06);color:#fff;font-size:18px;font-weight:600}
#rg-search input::placeholder{color:rgba(255,255,255,.5)}
#rg-search input:focus{outline:none;border-color:var(--rg-p);background:rgba(255,255,255,.1)}
#rg-search button[type=submit]{position:absolute;right:9px;top:9px;bottom:9px;width:52px;border-radius:12px;background:var(--rg-grad);color:#fff;display:grid;place-items:center}
#rg-search-close{position:absolute;top:26px;right:26px;width:46px;height:46px;border-radius:50%;color:#fff;background:rgba(255,255,255,.1);display:grid;place-items:center}
#rg-search-close:hover{background:var(--rg-p)}
.rg-search-tip{color:rgba(255,255,255,.65);margin-top:16px;font-size:14px;text-align:center}

/* ==========================================================================
   7. BREAKING TICKER
   ========================================================================== */
.rg-ticker{background:var(--rg-card);border-bottom:1px solid var(--rg-bd);overflow:hidden}
.rg-ticker .rg-container{display:flex;align-items:center;gap:14px;min-height:52px}
.rg-ticker-tag{display:inline-flex;align-items:center;gap:7px;background:var(--rg-grad);color:#fff;font-size:11.5px;
  font-weight:800;letter-spacing:1.2px;text-transform:uppercase;padding:7px 14px;border-radius:8px;flex:0 0 auto}
.rg-ticker-view{position:relative;overflow:hidden;flex:1 1 auto;height:52px}
.rg-ticker-list{position:absolute;inset:0;display:flex;align-items:center;gap:38px;white-space:nowrap;
  animation:rg-marquee 34s linear infinite;will-change:transform}
.rg-ticker-view:hover .rg-ticker-list{animation-play-state:paused}
.rg-ticker-list a{color:var(--rg-text);font-size:14px;font-weight:600;display:inline-flex;align-items:center;gap:9px}
.rg-ticker-list a::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--rg-p)}
.rg-ticker-list a:hover{color:var(--rg-p)}
@keyframes rg-marquee{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
.rg-ticker-fallback{font-size:14px;color:var(--rg-muted)}

/* ==========================================================================
   8. LAYOUT
   ========================================================================== */
.rg-main{padding:34px 0 46px}
.rg-layout{display:grid;grid-template-columns:minmax(0,1fr) 336px;gap:34px;align-items:start}
.rg-content{min-width:0}
.rg-sidebar{position:sticky;top:calc(var(--rg-head-h) + 18px);display:flex;flex-direction:column;gap:26px}
.rg-sec-head{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:0 0 20px;padding-bottom:12px;
  border-bottom:2px solid var(--rg-bd);position:relative}
.rg-sec-head::before{content:"";position:absolute;left:0;bottom:-2px;width:64px;height:2px;background:var(--rg-grad)}
.rg-sec-title{font-size:20px;margin:0;display:flex;align-items:center;gap:10px;letter-spacing:-.4px}
.rg-sec-title .dot{width:9px;height:9px;border-radius:2px;background:var(--rg-grad);transform:rotate(45deg)}
.rg-sec-link{font-size:12.5px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.rg-page-head{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);padding:26px 28px;margin-bottom:26px;box-shadow:var(--rg-shadow)}
.rg-page-head h1{font-size:26px;margin:0}
.rg-page-head p{margin:8px 0 0;color:var(--rg-muted);font-size:14.5px}

/* ==========================================================================
   9. FEATURED / HERO (homepage)
   ========================================================================== */
.rg-featured{display:grid;grid-template-columns:1.55fr 1fr;grid-auto-rows:minmax(210px,auto);gap:18px;margin-bottom:38px}
.rg-card{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);overflow:hidden;
  box-shadow:var(--rg-shadow);display:flex;flex-direction:column;position:relative;
  transition:transform .45s var(--rg-ease),box-shadow .45s var(--rg-ease),border-color .3s}
.rg-card:hover{transform:translateY(-6px);box-shadow:var(--rg-shadow-lg);border-color:rgba(229,9,75,.25)}
.rg-thumb{position:relative;display:block;overflow:hidden;background:linear-gradient(135deg,#1b2338,#0e1424);aspect-ratio:16/10}
.rg-thumb img{width:100%;height:100%;object-fit:cover;transition:transform .8s var(--rg-ease),opacity .6s}
.rg-card:hover .rg-thumb img{transform:scale(1.07)}
.rg-thumb::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(10,14,26,0) 40%,rgba(10,14,26,.72) 100%);opacity:.9}
.rg-noimg{position:absolute;inset:0;display:grid;place-items:center;background:var(--rg-grad);color:#fff;
  font-family:$(headingFontFamily);font-weight:800;font-size:38px;letter-spacing:2px}
.rg-chip{position:absolute;left:14px;top:14px;z-index:3;display:inline-flex;align-items:center;gap:6px;
  background:var(--rg-grad);color:#fff;font-size:10.5px;font-weight:800;letter-spacing:1.1px;text-transform:uppercase;
  padding:6px 12px;border-radius:7px;box-shadow:0 6px 16px rgba(229,9,75,.3)}
.rg-chip:hover{color:#fff}
.rg-card-body{padding:18px 20px 20px;display:flex;flex-direction:column;gap:9px;flex:1 1 auto}
.rg-card-title{font-size:18px;margin:0;line-height:1.35}
.rg-card-title a{color:var(--rg-h);background-image:linear-gradient(var(--rg-p),var(--rg-p));background-size:0 2px;
  background-repeat:no-repeat;background-position:0 100%;transition:background-size .4s var(--rg-ease),color .3s}
.rg-card-title a:hover{color:var(--rg-p);background-size:100% 2px}
.rg-excerpt{font-size:14px;color:var(--rg-muted);margin:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.rg-meta{display:flex;align-items:center;flex-wrap:wrap;gap:12px;font-size:12.5px;color:var(--rg-muted);margin-top:auto;padding-top:4px}
.rg-meta span{display:inline-flex;align-items:center;gap:6px}
.rg-meta .rg-by{font-weight:700;color:var(--rg-h)}
.rg-meta .rg-by img{width:22px;height:22px;border-radius:50%;object-fit:cover}
/* hero variants */
.rg-featured .rg-card:first-child{grid-row:span 2}
.rg-featured .rg-card:first-child .rg-thumb{aspect-ratio:16/12}
.rg-featured .rg-card:first-child .rg-card-title{font-size:27px}
.rg-featured .rg-card:first-child .rg-excerpt{-webkit-line-clamp:3;font-size:14.5px}
.rg-featured .rg-card:first-child .rg-card-body{padding:22px 24px 24px}
.rg-featured .rg-card:not(:first-child) .rg-card-body{padding:14px 16px 16px}
.rg-featured .rg-card:not(:first-child) .rg-card-title{font-size:15.5px}
.rg-featured .rg-card:not(:first-child) .rg-excerpt{display:none}
.rg-featured .rg-card:not(:first-child) .rg-thumb{aspect-ratio:16/8}
.rg-overlay-title{position:absolute;left:0;right:0;bottom:0;z-index:3;padding:18px;color:#fff}
.rg-overlay-title a{color:#fff}
.rg-overlay-title a:hover{color:#ffd6e2}

/* ==========================================================================
   10. POST GRID
   ========================================================================== */
.rg-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.rg-list{display:flex;flex-direction:column;gap:20px}
.rg-card-wide{display:grid;grid-template-columns:270px minmax(0,1fr)}
.rg-card-wide .rg-thumb{aspect-ratio:16/11;height:100%}
.rg-card-wide .rg-card-body{padding:20px 22px}
.rg-card-wide .rg-card-title{font-size:20px}

/* ==========================================================================
   11. SINGLE POST
   ========================================================================== */
.rg-crumbs{display:flex;align-items:center;flex-wrap:wrap;gap:8px;font-size:12.5px;color:var(--rg-muted);margin-bottom:18px}
.rg-crumbs a{color:var(--rg-muted);font-weight:600}
.rg-crumbs a:hover{color:var(--rg-p)}
.rg-crumbs .sep{opacity:.5}
.rg-crumbs .cur{color:var(--rg-h);font-weight:700}
.rg-post{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);padding:30px 32px;box-shadow:var(--rg-shadow)}
.rg-post-cats{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}
.rg-cat{display:inline-block;font-size:11px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--rg-p);
  background:rgba(229,9,75,.08);padding:6px 13px;border-radius:6px;transition:all .3s var(--rg-ease)}
.rg-cat:hover{background:var(--rg-p);color:#fff}
.rg-post h1.rg-post-title{font-size:34px;line-height:1.22;margin:0 0 16px}
.rg-post-meta{display:flex;align-items:center;flex-wrap:wrap;gap:16px;padding:16px 0;border-top:1px solid var(--rg-bd);
  border-bottom:1px solid var(--rg-bd);margin-bottom:24px;font-size:13.5px;color:var(--rg-muted)}
.rg-post-meta .rg-ava{display:flex;align-items:center;gap:10px;color:var(--rg-h);font-weight:700}
.rg-post-meta .rg-ava img{width:38px;height:38px;border-radius:50%;object-fit:cover;border:2px solid rgba(229,9,75,.25)}
.rg-hero-img{border-radius:var(--rg-r);overflow:hidden;margin:0 0 26px;border:1px solid var(--rg-bd)}
.rg-hero-img img{width:100%;height:auto}
.rg-body{font-size:17px;line-height:1.85;color:#3d4759;word-wrap:break-word}
.rg-body h2{font-size:25px;margin:38px 0 14px;padding-left:16px;border-left:4px solid var(--rg-p)}
.rg-body h3{font-size:20px;margin:30px 0 12px}
.rg-body h4{font-size:17.5px;margin:24px 0 10px}
.rg-body p{margin:0 0 20px}
.rg-body a{color:var(--rg-p);text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
.rg-body a:hover{background:var(--rg-p);color:#fff;text-decoration:none}
.rg-body img{border-radius:12px;margin:22px auto;box-shadow:var(--rg-shadow)}
.rg-body ul,.rg-body ol{margin:0 0 22px;padding-left:22px}
.rg-body ul{list-style:none}
.rg-body ul li{position:relative;padding-left:24px;margin-bottom:9px}
.rg-body ul li::before{content:"";position:absolute;left:0;top:10px;width:8px;height:8px;border-radius:2px;background:var(--rg-grad);transform:rotate(45deg)}
.rg-body ol{list-style:decimal}
.rg-body ol li{margin-bottom:9px;padding-left:6px}
.rg-body blockquote{margin:26px 0;padding:20px 24px;background:linear-gradient(120deg,rgba(229,9,75,.06),rgba(255,95,109,.05));
  border-left:4px solid var(--rg-p);border-radius:0 12px 12px 0;font-size:18px;font-style:italic;color:var(--rg-h);font-weight:600}
.rg-body blockquote p:last-child{margin:0}
.rg-body pre,.rg-body code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.rg-body pre{background:#0e1424;color:#e8ecf5;padding:20px;border-radius:12px;overflow:auto;margin:0 0 24px;font-size:14px;line-height:1.6}
.rg-body code{background:rgba(229,9,75,.09);color:var(--rg-p);padding:2px 7px;border-radius:5px;font-size:.92em}
.rg-body pre code{background:none;color:inherit;padding:0}
.rg-body table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:15px;border-radius:12px;overflow:hidden}
.rg-body th{background:var(--rg-dark);color:#fff;text-align:left;padding:12px 14px;font-weight:700}
.rg-body td{padding:11px 14px;border-bottom:1px solid var(--rg-bd)}
.rg-body tr:nth-child(even) td{background:var(--rg-soft)}
.rg-body hr{border:0;height:1px;background:var(--rg-bd);margin:32px 0}
.rg-body .tr-caption-container{margin:0 0 24px;text-align:center}
.rg-body .tr-caption{font-size:13px;color:var(--rg-muted);padding-top:8px}
/* TOC */
#rg-toc{background:var(--rg-soft);border:1px solid var(--rg-bd);border-radius:12px;padding:18px 22px;margin:0 0 28px}
#rg-toc .rg-toc-title{display:flex;align-items:center;justify-content:space-between;font-family:$(headingFontFamily);
  font-weight:800;font-size:15px;color:var(--rg-h);cursor:pointer}
#rg-toc ol{margin:12px 0 0;padding-left:20px;list-style:decimal;font-size:14.5px}
#rg-toc li{margin-bottom:7px}
#rg-toc a{color:var(--rg-text)}
#rg-toc a:hover{color:var(--rg-p)}
#rg-toc.collapsed ol{display:none}
/* tags + share */
.rg-tags{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin:30px 0 6px;padding-top:22px;border-top:1px solid var(--rg-bd)}
.rg-tags .lbl{font-weight:800;color:var(--rg-h);font-size:13px;letter-spacing:.4px;text-transform:uppercase}
.rg-share{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:22px 0 0;padding:20px 0;border-top:1px solid var(--rg-bd);border-bottom:1px solid var(--rg-bd)}
.rg-share .lbl{font-weight:800;color:var(--rg-h);font-size:13px;letter-spacing:.6px;text-transform:uppercase;margin-right:4px}
.rg-sh{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;color:#fff;transition:transform .3s var(--rg-ease),filter .3s}
.rg-sh:hover{transform:translateY(-4px) scale(1.06);color:#fff;filter:brightness(1.1)}
.rg-sh.wa{background:#25d366}.rg-sh.x{background:#000}.rg-sh.fb{background:#1877f2}
.rg-sh.li{background:#0a66c2}.rg-sh.tg{background:#229ed9}.rg-sh.copy{background:var(--rg-dark)}
/* author box */
.rg-author{display:flex;gap:20px;align-items:flex-start;background:linear-gradient(135deg,rgba(229,9,75,.05),rgba(14,20,36,.03));
  border:1px solid var(--rg-bd);border-radius:var(--rg-r);padding:24px;margin:26px 0}
.rg-author img{width:88px;height:88px;border-radius:50%;object-fit:cover;flex:0 0 auto;border:3px solid #fff;box-shadow:var(--rg-shadow)}
.rg-author h4{margin:0 0 4px;font-size:19px}
.rg-author .role{font-size:12px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--rg-p);margin-bottom:8px}
.rg-author p{font-size:14.5px;margin:0 0 12px}
.rg-author .rg-mini{display:flex;gap:7px;flex-wrap:wrap}
.rg-mini a{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#fff;color:var(--rg-h);
  border:1px solid var(--rg-bd);transition:all .3s var(--rg-ease)}
.rg-mini a:hover{background:var(--rg-p);border-color:var(--rg-p);color:#fff;transform:translateY(-3px)}
/* post pager */
.rg-pager{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:26px 0}
.rg-pager a{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);padding:16px 18px;
  display:flex;flex-direction:column;gap:6px;color:var(--rg-h);transition:all .35s var(--rg-ease)}
.rg-pager a:hover{border-color:var(--rg-p);transform:translateY(-3px);color:var(--rg-h)}
.rg-pager small{font-size:11px;font-weight:800;letter-spacing:1.1px;text-transform:uppercase;color:var(--rg-p)}
.rg-pager strong{font-size:14.5px;line-height:1.4}
.rg-pager .next{text-align:right;align-items:flex-end}

/* ==========================================================================
   12. SIDEBAR WIDGETS
   ========================================================================== */
.rg-widget{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);padding:22px;box-shadow:var(--rg-shadow)}
.rg-widget h3.rg-wtitle{font-size:16px;margin:0 0 18px;padding-bottom:12px;border-bottom:2px solid var(--rg-bd);position:relative;letter-spacing:-.2px}
.rg-widget h3.rg-wtitle::before{content:"";position:absolute;left:0;bottom:-2px;width:48px;height:2px;background:var(--rg-grad)}
.rg-widget .widget-content{font-size:14.5px}
/* about me */
.rg-about{text-align:center}
.rg-about .ava{width:96px;height:96px;border-radius:50%;margin:0 auto 14px;object-fit:cover;border:4px solid #fff;
  box-shadow:0 8px 22px rgba(229,9,75,.22);transition:transform .5s var(--rg-ease)}
.rg-about:hover .ava{transform:scale(1.06) rotate(3deg)}
.rg-about .nm{font-family:$(headingFontFamily);font-weight:800;font-size:18px;color:var(--rg-h)}
.rg-about .rl{font-size:11.5px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:var(--rg-p);margin-bottom:10px}
.rg-about p{font-size:14px;color:var(--rg-muted)}
.rg-about .rg-mini{justify-content:center;margin-top:14px}
/* popular posts */
.rg-pop{display:flex;gap:14px;padding:14px 0;border-bottom:1px dashed var(--rg-bd)}
.rg-pop:last-child{border-bottom:0;padding-bottom:0}
.rg-pop:first-child{padding-top:0}
.rg-pop .no{width:34px;height:34px;border-radius:9px;background:var(--rg-soft);color:var(--rg-h);display:grid;place-items:center;
  font-family:$(headingFontFamily);font-weight:800;font-size:14px;flex:0 0 auto;transition:all .3s var(--rg-ease)}
.rg-pop:hover .no{background:var(--rg-grad);color:#fff;transform:rotate(-6deg)}
.rg-pop .thumb{width:78px;height:64px;border-radius:9px;overflow:hidden;flex:0 0 auto}
.rg-pop .thumb img{width:100%;height:100%;object-fit:cover;transition:transform .6s var(--rg-ease)}
.rg-pop:hover .thumb img{transform:scale(1.12)}
.rg-pop h4{font-size:14px;line-height:1.45;margin:0 0 5px}
.rg-pop h4 a{color:var(--rg-h)}
.rg-pop h4 a:hover{color:var(--rg-p)}
.rg-pop .rg-d{font-size:11.5px;color:var(--rg-muted);display:inline-flex;align-items:center;gap:5px}
/* categories */
.rg-cats li{border-bottom:1px solid var(--rg-bd)}
.rg-cats li:last-child{border-bottom:0}
.rg-cats a{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 4px;color:var(--rg-h);font-weight:600;font-size:14.5px}
.rg-cats a:hover{color:var(--rg-p);padding-left:10px}
.rg-cats a::before{content:"";width:6px;height:6px;border-radius:2px;background:var(--rg-p);transform:rotate(45deg);opacity:0;transition:opacity .3s}
.rg-cats a:hover::before{opacity:1}
.rg-cats .cnt{font-size:11.5px;font-weight:700;color:var(--rg-muted);background:var(--rg-soft);padding:2px 9px;border-radius:20px}
/* tag cloud */
.rg-cloud{display:flex;flex-wrap:wrap;gap:8px}
.rg-cloud a{font-size:12.5px;font-weight:600;padding:7px 13px;border-radius:20px;background:var(--rg-soft);color:var(--rg-text);
  border:1px solid var(--rg-bd);transition:all .3s var(--rg-ease)}
.rg-cloud a:hover{background:var(--rg-grad);color:#fff;border-color:transparent;transform:translateY(-2px)}
/* newsletter */
.rg-news{background:var(--rg-dark);color:#fff;border:0;position:relative;overflow:hidden}
.rg-news::before{content:"";position:absolute;width:190px;height:190px;border-radius:50%;background:var(--rg-grad);
  opacity:.22;top:-70px;right:-60px;filter:blur(4px)}
.rg-news h3.rg-wtitle{color:#fff;border-color:rgba(255,255,255,.14)}
.rg-news h3.rg-wtitle::before{background:var(--rg-grad)}
.rg-news p{color:rgba(255,255,255,.72);font-size:14px;position:relative}
.rg-news form{display:flex;flex-direction:column;gap:10px;position:relative}
.rg-news input[type=email]{width:100%;padding:13px 15px;border-radius:10px;border:1px solid rgba(255,255,255,.18);
  background:rgba(255,255,255,.09);color:#fff;font-size:14px}
.rg-news input[type=email]::placeholder{color:rgba(255,255,255,.55)}
.rg-news input[type=email]:focus{outline:none;border-color:var(--rg-p)}
.rg-news button{padding:13px;border-radius:10px;background:var(--rg-grad);color:#fff;font-weight:700;font-size:14px;
  transition:transform .3s var(--rg-ease),box-shadow .3s}
.rg-news button:hover{transform:translateY(-2px);box-shadow:0 10px 22px rgba(229,9,75,.4)}
/* sidebar HTML widget / ads */
.rg-html .widget-content{line-height:1.7}
.rg-html img{border-radius:10px;margin:0 auto}

/* ==========================================================================
   13. RELATED POSTS
   ========================================================================== */
.rg-related{margin-top:34px}
.rg-related .rg-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
#rg-related.loading{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.rg-skel{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);overflow:hidden;height:230px;
  background-image:linear-gradient(100deg,var(--rg-card) 30%,var(--rg-soft) 50%,var(--rg-card) 70%);
  background-size:220% 100%;animation:rg-shimmer 1.4s infinite linear}
@keyframes rg-shimmer{0%{background-position:180% 0}100%{background-position:-80% 0}}

/* ==========================================================================
   14. COMMENTS
   ========================================================================== */
.rg-comments{background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);padding:26px 28px;margin-top:26px;box-shadow:var(--rg-shadow)}
.rg-comments h3{font-size:19px;margin:0 0 20px;padding-bottom:12px;border-bottom:2px solid var(--rg-bd);position:relative}
.rg-comments h3::before{content:"";position:absolute;left:0;bottom:-2px;width:52px;height:2px;background:var(--rg-grad)}
.rg-cmt{display:flex;gap:14px;padding:18px 0;border-bottom:1px dashed var(--rg-bd)}
.rg-cmt:last-child{border-bottom:0}
.rg-cmt img.rg-cava{width:42px;height:42px;border-radius:50%;object-fit:cover;flex:0 0 auto}
.rg-cmt-head{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:5px}
.rg-cmt-head .nm{font-weight:700;color:var(--rg-h);font-size:14.5px}
.rg-cmt-head .dt{font-size:12px;color:var(--rg-muted)}
.rg-cmt-body{font-size:14.5px;margin:0}
.rg-cmt-replies{margin:14px 0 0 0;padding-left:18px;border-left:3px solid var(--rg-bd)}
.rg-cmt-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
#comment-editor{width:100%;border:1px solid var(--rg-bd);border-radius:12px;margin-top:14px;background:var(--rg-card)}

/* ==========================================================================
   15. PAGINATION
   ========================================================================== */
.rg-pagination{display:flex;align-items:center;justify-content:center;gap:12px;margin:38px 0 6px;flex-wrap:wrap}
.rg-pagination a{display:inline-flex;align-items:center;gap:8px;padding:12px 22px;border-radius:50px;background:var(--rg-card);
  border:1px solid var(--rg-bd);color:var(--rg-h);font-weight:700;font-size:13.5px;box-shadow:var(--rg-shadow);
  transition:all .3s var(--rg-ease)}
.rg-pagination a:hover{background:var(--rg-grad);border-color:transparent;color:#fff;transform:translateY(-3px)}

/* ==========================================================================
   16. FOOTER
   ========================================================================== */
.rg-footer{background:var(--rg-dark);color:#a9b3c6;margin-top:44px;position:relative;overflow:hidden}
.rg-footer::before{content:"";position:absolute;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,rgba(229,9,75,.2),transparent 70%);top:-180px;left:-120px}
.rg-footer .rg-container{position:relative}
.rg-foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:34px;padding:52px 0 34px}
.rg-foot-grid h3{color:#fff;font-size:15.5px;margin:0 0 18px;position:relative;padding-bottom:11px}
.rg-foot-grid h3::after{content:"";position:absolute;left:0;bottom:0;width:36px;height:2px;background:var(--rg-grad)}
.rg-foot-about p{font-size:14px;line-height:1.8}
.rg-foot-about .rg-mini{margin-top:16px}
.rg-foot-about .rg-mini a{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.1);color:#dbe2f0}
.rg-foot-about .rg-mini a:hover{background:var(--rg-p);border-color:var(--rg-p);color:#fff}
.rg-foot-list li{margin-bottom:10px}
.rg-foot-list a{color:#a9b3c6;font-size:14px;display:inline-flex;align-items:center;gap:8px;transition:all .3s var(--rg-ease)}
.rg-foot-list a::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--rg-p);transition:transform .3s}
.rg-foot-list a:hover{color:#fff;padding-left:6px}
.rg-foot-list a:hover::before{transform:scale(1.6)}
.rg-foot-contact li{display:flex;gap:10px;margin-bottom:12px;font-size:14px;align-items:flex-start}
.rg-foot-contact .rg-icon{color:var(--rg-p);margin-top:3px}
.rg-copy{border-top:1px solid rgba(255,255,255,.09);padding:18px 0;font-size:13.5px}
.rg-copy .rg-container{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}
.rg-copy a{color:#dbe2f0;font-weight:600}
.rg-copy a:hover{color:var(--rg-p)}
.rg-copy .heart{color:var(--rg-p)}
.rg-foot-nav{display:flex;gap:16px;flex-wrap:wrap}

/* ==========================================================================
   17. 404
   ========================================================================== */
.rg-404{text-align:center;padding:64px 20px;background:var(--rg-card);border:1px solid var(--rg-bd);border-radius:var(--rg-r);box-shadow:var(--rg-shadow)}
.rg-404 .big{font-family:$(headingFontFamily);font-size:96px;font-weight:800;line-height:1;background:var(--rg-grad);
  -webkit-background-clip:text;background-clip:text;color:transparent;margin-bottom:8px}
.rg-404 h2{font-size:24px;margin-bottom:10px}
.rg-404 p{color:var(--rg-muted);max-width:460px;margin:0 auto 24px}

/* ==========================================================================
   18. ANIMATIONS (scroll reveal)
   ========================================================================== */
.rg-reveal{opacity:0;transform:translateY(26px);transition:opacity .7s var(--rg-ease),transform .7s var(--rg-ease)}
.rg-reveal.in{opacity:1;transform:none}
.rg-reveal:nth-child(2){transition-delay:.07s}
.rg-reveal:nth-child(3){transition-delay:.14s}
.rg-reveal:nth-child(4){transition-delay:.21s}
.rg-reveal:nth-child(5){transition-delay:.28s}
.rg-reveal:nth-child(6){transition-delay:.35s}
img.rg-lazy{animation:rg-imgin .8s var(--rg-ease) both}
img.rg-lazy.loaded{animation:none}
@keyframes rg-imgin{from{opacity:0;transform:scale(1.03)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;scroll-behavior:auto!important}
  .rg-reveal{opacity:1;transform:none}
}

/* ==========================================================================
   19. DARK MODE
   ========================================================================== */
body.rg-dark{--rg-bg:#0a0f1c;--rg-card:#111828;--rg-h:#eef2fb;--rg-text:#a9b4c8;--rg-bd:#1e2739;--rg-soft:#0f1626;--rg-muted:#7d889e}
body.rg-dark .rg-header,body.rg-dark .rg-nav,body.rg-dark .rg-ticker{background:#111828}
body.rg-dark .rg-sh.x{background:#2a3244}
body.rg-dark .rg-body{color:#c3ccdd}
body.rg-dark .rg-body code{background:rgba(229,9,75,.18)}
body.rg-dark .rg-topbar{background:#070b14}
body.rg-dark ::-webkit-scrollbar-track{background:#0f1626}
body.rg-dark ::-webkit-scrollbar-thumb{background:#2b3549}

/* ==========================================================================
   20. RESPONSIVE
   ========================================================================== */
@media (max-width:1080px){
  .rg-layout{grid-template-columns:minmax(0,1fr) 300px;gap:26px}
  .rg-grid,.rg-related .rg-grid,#rg-related.loading{grid-template-columns:repeat(2,minmax(0,1fr))}
  .rg-foot-grid{grid-template-columns:1fr 1fr;gap:30px}
}
@media (max-width:900px){
  .rg-layout{grid-template-columns:minmax(0,1fr)}
  .rg-sidebar{position:static}
  .rg-featured{grid-template-columns:1fr;grid-auto-rows:auto}
  .rg-featured .rg-card:first-child{grid-row:auto}
  .rg-featured .rg-card:first-child .rg-card-title{font-size:22px}
  #rg-menu-list{display:none}
  .rg-nav-side{margin-left:auto}
  .rg-burger{display:grid}
  .rg-post{padding:24px 20px}
  .rg-post h1.rg-post-title{font-size:27px}
  .rg-body{font-size:16.5px}
  .rg-date{display:none}
}
@media (max-width:680px){
  :root{--rg-head-h:58px}
  .rg-header .rg-container{min-height:66px}
  .rg-logo-name{font-size:21px}
  .rg-mark{width:38px;height:38px;font-size:15px;border-radius:10px}
  .rg-grid,.rg-related .rg-grid,#rg-related.loading{grid-template-columns:minmax(0,1fr)}
  .rg-card-wide{grid-template-columns:minmax(0,1fr)}
  .rg-card-wide .rg-thumb{aspect-ratio:16/9}
  .rg-foot-grid{grid-template-columns:1fr;padding:40px 0 26px}
  .rg-pager{grid-template-columns:1fr}
  .rg-pager .next{text-align:left;align-items:flex-start}
  .rg-author{flex-direction:column;text-align:center;align-items:center}
  .rg-author .rg-mini{justify-content:center}
  .rg-subscribe{display:none}
  .rg-ticker{display:none}
  .rg-copy .rg-container{justify-content:center;text-align:center}
  .rg-sec-title{font-size:18px}
}
@media (max-width:420px){
  .rg-container{padding:0 14px}
  .rg-post h1.rg-post-title{font-size:23px}
  .rg-body h2{font-size:21px}
}
body:not(.layout-mode) .rg-sec-navbar,body:not(.layout-mode) #navbar-iframe{display:none!important;height:0!important}
/* Blogger widget wrappers must not break the flex/grid layout */
body:not(.layout-mode) .rg-sec-header,body:not(.layout-mode) .rg-sec-header .widget,
body:not(.layout-mode) .rg-sec-menu,body:not(.layout-mode) .rg-sec-menu .widget,
body:not(.layout-mode) .rg-sec-drawer,body:not(.layout-mode) .rg-sec-drawer .widget,
body:not(.layout-mode) .rg-sec-copy,body:not(.layout-mode) .rg-sec-copy .widget{display:contents}
body:not(.layout-mode) .rg-sec-side,body:not(.layout-mode) .rg-sec-side .widget,
body:not(.layout-mode) .rg-sec-foot,body:not(.layout-mode) .rg-sec-foot .widget,
body:not(.layout-mode) .rg-sec-main,body:not(.layout-mode) .rg-sec-main .widget{display:contents}
.rg-sec-side,.rg-sec-foot{display:flex;flex-direction:column;gap:26px}
.rg-foot-grid .rg-sec-foot{gap:0}
.widget .widget-content{line-height:1.7}
/* Blogger layout mode (admin drag & drop) */
body.layout-mode .rg-sidebar,body.layout-mode .rg-topbar{display:block}

body.script:
//
var RG=window.RG||{};
(function(){
'use strict';
var d=document,w=window;
function $(s,c){return (c||d).querySelector(s);}
function $$(s,c){return Array.prototype.slice.call((c||d).querySelectorAll(s));}

/* ---------- date + year ---------- */
function initDate(){
  var el=$('#rg-date');
  if(el){
    try{
      var o={weekday:'long',day:'numeric',month:'long',year:'numeric'};
      el.textContent=new Date().toLocaleDateString('en-IN',o);
    }catch(e){el.textContent=new Date().toDateString();}
  }
  var y=$('#rg-year'); if(y){y.textContent=new Date().getFullYear();}
}

/* ---------- dark mode ---------- */
function initMode(){
  var btn=$('#rg-mode'),ico=$('#rg-mode-icon');
  function paint(){
    var dark=d.body.classList.contains('rg-dark');
    if(ico){ico.setAttribute('xlink:href',dark?'#i-sun':'#i-moon');}
  }
  paint();
  if(btn){
    btn.addEventListener('click',function(){
      d.body.classList.toggle('rg-dark');
      var dark=d.body.classList.contains('rg-dark');
      try{localStorage.setItem('rg-mode',dark?'dark':'light');}catch(e){}
      paint();
    });
  }
}

/* ---------- sticky nav + reading progress + back to top ---------- */
function initScroll(){
  var nav=$('#rg-nav'),bar=$('#rg-progress'),top=$('#rg-top'),tick=false;
  function upd(){
    var y=w.pageYOffset||d.documentElement.scrollTop;
    if(nav){nav.classList.toggle('stuck',y>10);}
    if(top){top.classList.toggle('show',y>500);}
    if(bar){
      var h=d.documentElement.scrollHeight-w.innerHeight;
      bar.style.width=(h>0?(y/h)*100:0)+'%';
    }
    tick=false;
  }
  w.addEventListener('scroll',function(){if(!tick){tick=true;w.requestAnimationFrame(upd);}},{passive:true});
  upd();
  if(top){top.addEventListener('click',function(){w.scrollTo({top:0,behavior:'smooth'});});}
}

/* ---------- mobile drawer ---------- */
function initDrawer(){
  var burger=$('#rg-burger'),drawer=$('#rg-drawer'),ov=$('#rg-overlay'),cls=$('#rg-drawer-close');
  function open(){if(drawer){drawer.classList.add('open');}if(ov){ov.classList.add('show');}d.body.style.overflow='hidden';}
  function close(){if(drawer){drawer.classList.remove('open');}if(ov){ov.classList.remove('show');}d.body.style.overflow='';}
  if(burger){burger.addEventListener('click',open);}
  if(cls){cls.addEventListener('click',close);}
  if(ov){ov.addEventListener('click',close);}
}

/* ---------- search overlay ---------- */
function initSearch(){
  var box=$('#rg-search'),inp=$('#rg-search-input'),cls=$('#rg-search-close');
  function open(){if(box){box.classList.add('open');d.body.style.overflow='hidden';if(inp){setTimeout(function(){inp.focus();},260);}}}
  function close(){if(box){box.classList.remove('open');d.body.style.overflow='';}}
  $$('.rg-search-btn').forEach(function(b){b.addEventListener('click',open);});
  if(cls){cls.addEventListener('click',close);}
  if(box){box.addEventListener('click',function(e){if(e.target===box){close();}});}
  d.addEventListener('keydown',function(e){if(e.key==='Escape'){close();}});
}

/* ---------- scroll reveal animation ---------- */
function initReveal(){
  var items=$$('.rg-reveal');
  if(!items.length){return;}
  if(!('IntersectionObserver' in w)){items.forEach(function(i){i.classList.add('in');});return;}
  var io=new IntersectionObserver(function(en){
    en.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});
  },{rootMargin:'0px 0px -8% 0px',threshold:.06});
  items.forEach(function(i){io.observe(i);});
}

/* ---------- reading time ---------- */
function initReadTime(){
  var body=$('#rg-body'),el=$('#rg-readtime');
  if(!body||!el){return;}
  var words=(body.innerText||body.textContent||'').trim().split(/\s+/).length;
  var mins=Math.max(1,Math.round(words/200));
  el.textContent=mins+' min read';
}

/* ---------- auto table of contents ---------- */
function initTOC(){
  var body=$('#rg-body'),toc=$('#rg-toc');
  if(!body||!toc){return;}
  var hs=$$('h2, h3',body);
  if(hs.length<3){return;}
  var ol=$('ol',toc),html='';
  hs.slice(0,14).forEach(function(h,i){
    if(!h.id){h.id='rg-sec-'+(i+1);}
    html+='<li><a href="#'+h.id+'">'+h.textContent.trim()+'</a></li>';
  });
  ol.innerHTML=html;
  toc.style.display='block';
  var t=$('.rg-toc-title',toc);
  if(t){t.addEventListener('click',function(){toc.classList.toggle('collapsed');});}
}

/* ---------- copy link ---------- */
function initCopy(){
  $$('[data-copy="copy"]').forEach(function(b){
    b.addEventListener('click',function(){
      var u=b.getAttribute('data-url')||location.href;
      function done(){var o=b.getAttribute('title');b.setAttribute('title','Copied!');setTimeout(function(){b.setAttribute('title',o||'Copy link');},1800);}
      if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(u).then(done,done);}
      else{
        var t=d.createElement('textarea');t.value=u;t.style.position='fixed';t.style.opacity='0';d.body.appendChild(t);t.select();
        try{d.execCommand('copy');}catch(e){}
        d.body.removeChild(t);done();
      }
    });
  });
}

/* ---------- inline comment form ---------- */
function initComments(){
  var btn=$('#rg-cmt-open'),fr=$('#comment-editor');
  if(!btn||!fr){return;}
  btn.addEventListener('click',function(e){
    e.preventDefault();
    if(fr.getAttribute('src')){fr.scrollIntoView({behavior:'smooth',block:'center'});return;}
    fr.setAttribute('src',btn.getAttribute('href'));
    fr.style.display='block';
    setTimeout(function(){fr.scrollIntoView({behavior:'smooth',block:'center'});},120);
  });
}

/* ---------- JSONP helper (Blogger feed) ---------- */
RG.jsonp=function(url,cb){
  var n='rgcb'+Math.random().toString(36).slice(2);
  w[n]=function(data){try{cb(data);}finally{delete w[n];if(s&&s.parentNode){s.parentNode.removeChild(s);}}};
  var s=d.createElement('script');
  s.src=url+(url.indexOf('?')>-1?'&':'?')+'callback='+n;
  s.async=true;
  s.onerror=function(){delete w[n];if(s.parentNode){s.parentNode.removeChild(s);}};
  d.head.appendChild(s);
};
function esc(s){return String(s||'').replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
function thumb(e){
  var m=e.media$thumbnail&&e.media$thumbnail.url?e.media$thumbnail.url:'';
  if(!m&&e.content){var x=/<img[^>]+src=["']([^"']+)["']/i.exec(e.content.$t||'');if(x){m=x[1];}}
  if(m){m=m.replace(/\/s72(-c)?\//,'/w600-h380-p-k-no-nu/').replace(/=s72(-c)?$/,'=w600-h380-p-k-no-nu');}
  return m;
}

/* ---------- breaking / trending ticker ---------- */
RG.ticker=function(data){
  var box=$('#rg-ticker-list');
  if(!box||!data.feed||!data.feed.entry){if(box){box.innerHTML='<span class="rg-ticker-fallback">Latest updates will appear here.</span>';}return;}
  var html='';
  data.feed.entry.slice(0,10).forEach(function(e){
    var link='#',title=(e.title&&e.title.$t)?e.title.$t:'';
    if(!title){return;}
    (e.link||[]).forEach(function(l){if(l.rel==='alternate'){link=l.href;}});
    html+='<a href="'+esc(link)+'">'+esc(title)+'</a>';
  });
  box.innerHTML=html+html;
};
function initTicker(){
  if(!$('#rg-ticker-list')){return;}
  RG.jsonp('/feeds/posts/default?alt=json-in-script&max-results=10&orderby=published',RG.ticker);
}

/* ---------- related posts ---------- */
RG.related=function(data){
  var box=$('#rg-related');
  if(!box){return;}
  var wrap=$('#rg-related-wrap'),cur=wrap?wrap.getAttribute('data-id'):'';
  var list=(data.feed&&data.feed.entry)?data.feed.entry:[];
  list=list.filter(function(e){return ((e.id&&e.id.$t)||'').indexOf(cur)===-1;});
  if(!list.length){box.className='';box.innerHTML='<p style="color:var(--rg-muted);font-size:14px">No related stories yet. Check the latest stories below.</p>';return;}
  var html='';
  list.slice(0,3).forEach(function(e){
    var link='#',cat='',title=(e.title&&e.title.$t)?e.title.$t:'';
    if(!title){return;}
    (e.link||[]).forEach(function(l){if(l.rel==='alternate'){link=l.href;}});
    if(e.category&&e.category[0]){cat=e.category[0].term;}
    var t=thumb(e),date=(e.published&&e.published.$t)?e.published.$t.substring(0,10):'';
    html+='<article class="rg-card rg-reveal in">'
      +'<a class="rg-thumb" href="'+esc(link)+'">'
      +(cat?'<span class="rg-chip">'+esc(cat)+'</span>':'')
      +(t?'<img alt="'+esc(title)+'" src="'+esc(t)+'" loading="lazy"/>':'<span class="rg-noimg">RG</span>')
      +'</a>'
      +'<div class="rg-card-body"><h3 class="rg-card-title"><a href="'+esc(link)+'">'+esc(title)+'</a></h3>'
      +'<div class="rg-meta"><span><svg class="rg-icon" style="width:14px;height:14px"><use xlink:href="#i-cal"/></svg> '
      +esc(date)+'</span></div></div></article>';
  });
  box.className='rg-grid';
  box.innerHTML=html;
};
function initRelated(){
  var wrap=$('#rg-related-wrap');
  if(!wrap){return;}
  var label=wrap.getAttribute('data-label');
  var base='/feeds/posts/default';
  if(label){base+='/-/'+encodeURIComponent(label);}
  RG.jsonp(base+'?alt=json-in-script&max-results=8&orderby=published',RG.related);
}

/* ---------- boot ---------- */
function boot(){
  initDate();initMode();initScroll();initDrawer();initSearch();initReveal();
  initReadTime();initTOC();initCopy();initComments();initTicker();initRelated();
  $$('img.rg-lazy').forEach(function(i){
    if(i.complete){i.classList.add('loaded');}
    else{i.addEventListener('load',function(){i.classList.add('loaded');});i.addEventListener('error',function(){i.classList.add('loaded');});}
  });
}
if(d.readyState==='loading'){d.addEventListener('DOMContentLoaded',boot);}else{boot();}
})();
//
